import { z } from "zod";

/**
 * ELISE Desktop releases (ADR-082): one canonical manifest, generated by the release pipeline
 * from the same build the auto-updater serves. The web download page reads it; React never
 * holds a download URL.
 *
 * - draft: built, not offered to anyone;
 * - published on "beta": only where beta downloads are on (development, preview, explicit beta);
 * - published on "stable": everyone — and only if the installer is signed;
 * - withdrawn: never offered again (the previous release takes its place).
 */
export const DESKTOP_PLATFORMS = ["windows", "macos"] as const;
export type DesktopPlatform = (typeof DESKTOP_PLATFORMS)[number];
export const DESKTOP_CHANNELS = ["stable", "beta"] as const;
export type DesktopChannel = (typeof DESKTOP_CHANNELS)[number];

const releaseSchema = z.object({
  version: z.string().regex(/^\d+\.\d+\.\d+(?:-[\w.]+)?$/),
  channel: z.enum(DESKTOP_CHANNELS),
  state: z.enum(["draft", "published", "withdrawn"]),
  platform: z.enum(DESKTOP_PLATFORMS),
  arch: z.enum(["x64", "arm64"]),
  installerUrl: z.url(),
  sha256: z.string().regex(/^[0-9a-f]{64}$/),
  sizeBytes: z.number().int().positive().optional(),
  publishedAt: z.iso.datetime(),
  signed: z.boolean(),
  minimumSupportedBridgeProtocol: z.number().int().min(1).optional(),
});
export type DesktopRelease = z.infer<typeof releaseSchema>;

export const desktopManifestSchema = z.object({
  schemaVersion: z.literal(1),
  releases: z.array(releaseSchema).max(500),
});
export type DesktopManifest = z.infer<typeof desktopManifestSchema>;

/** Parses a manifest; anything malformed means "no release", never a broken link. */
export function parseManifest(raw: unknown): DesktopManifest | null {
  const r = desktopManifestSchema.safeParse(raw);
  return r.success ? r.data : null;
}

const semver = (v: string) => v.split(/[.-]/).map((p) => (/^\d+$/.test(p) ? Number(p) : p));
export function compareVersions(a: string, b: string): number {
  const [x, y] = [semver(a), semver(b)];
  for (let i = 0; i < Math.max(x.length, y.length); i++) {
    const [p, q] = [x[i], y[i]];
    if (p === q) continue;
    if (p === undefined) return 1; // 1.0.0 > 1.0.0-beta.1
    if (q === undefined) return -1;
    if (typeof p === "number" && typeof q === "number") return p - q;
    return String(p) < String(q) ? -1 : 1;
  }
  return 0;
}

/**
 * The newest release this audience may download for a platform. Stable audiences get signed
 * stable builds only; beta audiences get the newest of beta or stable.
 */
export function latestRelease(
  manifest: DesktopManifest | null,
  options: {
    platform: DesktopPlatform;
    channel: DesktopChannel;
    arch?: "x64" | "arm64";
    production: boolean;
  },
): DesktopRelease | null {
  if (!manifest) return null;
  const candidates = manifest.releases.filter(
    (r) =>
      r.state === "published" &&
      r.platform === options.platform &&
      r.arch === (options.arch ?? "x64") &&
      (options.channel === "beta" || r.channel === "stable") &&
      // An unsigned build never reaches a production audience as stable.
      (!options.production || r.signed || options.channel === "beta") &&
      (!options.production || r.installerUrl.startsWith("https://")),
  );
  return candidates.sort((a, b) => compareVersions(b.version, a.version))[0] ?? null;
}

/** The platform a browser most likely runs on (a suggestion: the person can pick another). */
export function platformFromUserAgent(ua: string | null): DesktopPlatform | null {
  if (!ua) return null;
  if (/Windows NT/i.test(ua)) return "windows";
  if (/Macintosh|Mac OS X/i.test(ua) && !/iPhone|iPad|Mobile/i.test(ua)) return "macos";
  return null;
}
